import sqlite3

def handle(query, state):
    flag = state.get("flag", "")
    username = (query.get("username") or [""])[0]

    conn = sqlite3.connect(":memory:")
    cur = conn.cursor()

    cur.execute(
        "CREATE TABLE users (id INTEGER PRIMARY KEY, username TEXT, password TEXT, role TEXT)"
    )
    cur.execute(
        "CREATE TABLE secrets (id INTEGER PRIMARY KEY, user_id INTEGER, secret_data TEXT)"
    )
    cur.executemany(
        "INSERT INTO users (username, password, role) VALUES (?, ?, ?)",
        [("alice", "pass123", "user"), ("bob", "pass456", "user"), ("admin", "admin_pass", "admin")],
    )
    cur.executemany(
        "INSERT INTO secrets (user_id, secret_data) VALUES (?, ?)",
        [(1, "alice_secret"), (2, "bob_secret"), (3, flag)],
    )
    conn.commit()

    sql = "SELECT username, role FROM users WHERE username = '" + username + "'"
    try:
        cur.execute(sql)
        rows = cur.fetchall()
    except sqlite3.Error as e:
        conn.close()
        return 500, {"Content-Type": "text/plain"}, "Error: " + str(e)

    conn.close()

    if not rows:
        return 200, {"Content-Type": "text/plain"}, "User not found."

    lines = []
    for row in rows:
        lines.append("|".join(str(c) for c in row))
    return 200, {"Content-Type": "text/plain"}, "\n".join(lines)
